<template><div><section class="panel"><div class="panel-title"><h2>{{$t("挂号记录")}}</h2><el-button v-if="canEdit" icon="el-icon-plus" type="primary" @click="open">{{$t("现场挂号")}}</el-button></div><div class="toolbar"><el-input v-model.trim="q" clearable :placeholder="$t('姓名 / 病历号')" @keyup.enter.native="load"/><el-button @click="load">{{$t("查询")}}</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="id" :label="$t('挂号单号')" width="95"/><el-table-column prop="case_number" :label="$t('病历号')" min-width="110"/><el-table-column prop="real_name" :label="$t('患者')" width="100"/><el-table-column :formatter="localizedCell" prop="dept_name" :label="$t('科室')" width="110"/><el-table-column :formatter="localizedCell" prop="doctor" :label="$t('医生')" width="100"/><el-table-column :label="$t('就诊时间')" min-width="145"><template slot-scope="s">{{$t(String(s.row.visit_date).slice(0,10))}} {{$t(s.row.noon)}}</template></el-table-column><el-table-column :label="$t('状态')" width="115"><template slot-scope="s"><el-tag size="small" :type="tagType(s.row.visit_state)">{{$t(state(s.row.visit_state))}}</el-tag></template></el-table-column><el-table-column prop="regist_money" :label="$t('挂号金额')" width="100"/><el-table-column v-if="canEdit" :label="$t('操作')" width="100" fixed="right"><template slot-scope="s"><el-button v-if="s.row.visit_state==='WAITING'" type="text" @click="cancel(s.row)">{{$t("退号")}}</el-button><span v-else class="muted">—</span></template></el-table-column></el-table></section><el-dialog :title="$t('现场挂号')" :visible.sync="dialog" width="650px" :close-on-click-modal="false" append-to-body><el-form label-position="top"><div class="form-grid"><el-form-item :label="$t('患者')" required><el-select v-model="form.patientId" class="full" filterable remote :remote-method="searchPatient" :placeholder="$t('输入姓名或病历号搜索')" :loading="searching"><el-option v-for="p in patients" :key="p.id" :value="p.id" :label="$t(`${p.real_name}（${p.case_number}）`)"/></el-select></el-form-item><el-form-item :label="$t('结算类别')" required><el-select v-model="form.settleId" class="full"><el-option v-for="x in meta.settlements" :key="x.id" :label="$t(x.settle_name)" :value="x.id"/></el-select></el-form-item><el-form-item :label="$t('就诊日期')" required><el-date-picker v-model="form.date" type="date" value-format="yyyy-MM-dd" class="full" :picker-options="{disabledDate: d=>d.getTime()<Date.now()-86400000}" @change="loadSlots"/></el-form-item><el-form-item :label="$t('午别')" required><el-select v-model="form.period" class="full" @change="loadSlots"><el-option :label="$t('上午')" value="上午"/><el-option :label="$t('下午')" value="下午"/></el-select></el-form-item><el-form-item :label="$t('出诊医生')" required class="full-width"><el-select v-model="form.doctorId" class="full" :placeholder="$t('先选择日期和时段')" @change="doctorChanged"><el-option v-for="s in slots" :key="s.employee_id" :value="s.employee_id" :disabled="s.used>=s.capacity" :label="$t(`${s.realname} · ${s.dept_name} · 余号 ${s.capacity-s.used}`)"/></el-select></el-form-item><el-form-item :label="$t('病历本（另收费1元）')"><el-switch v-model="form.book"/></el-form-item></div></el-form><span slot="footer"><el-button @click="dialog=false">{{$t("取消")}}</el-button><el-button type="primary" :loading="saving" :disabled="saving" @click="submit">{{$t("确认挂号并收取挂号费")}}</el-button></span></el-dialog></div></template>
<script>import api from '../api';const today=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};export default{name:'Registrations',props:['meta','user'],data(){return{q:'',rows:[],loading:false,dialog:false,saving:false,searching:false,patients:[],slots:[],form:{patientId:null,settleId:null,doctorId:null,levelId:null,date:today(),period:'上午',book:false}}},computed:{canEdit(){return['ADMIN','REGISTRAR'].includes(this.user.role)}},created(){this.load()},methods:{state(x){return{WAITING:'待接诊',IN_PROGRESS:'诊疗中',COMPLETED:'已诊毕',CANCELLED:'已退号'}[x]||x},tagType(x){return{WAITING:'warning',IN_PROGRESS:'',COMPLETED:'success',CANCELLED:'info'}[x]},async load(){this.loading=true;try{this.rows=await api.get('/registrations',{params:{q:this.q}})}catch(e){this.$message.error(e.message)}finally{this.loading=false}},async searchPatient(q){if(!q)return;this.searching=true;try{this.patients=await api.get('/patients',{params:{q}})}catch(e){this.$message.error(e.message)}finally{this.searching=false}},async loadSlots(){this.form.doctorId=null;try{this.slots=await api.get('/schedules',{params:{date:this.form.date,period:this.form.period}})}catch(e){this.$message.error(e.message)}},doctorChanged(){let doctor=this.meta.doctors.find(x=>x.id===this.form.doctorId);this.form.levelId=doctor?doctor.regist_level_id:null},async open(){this.dialog=true;this.form.requestId=Date.now().toString(36)+Math.random().toString(36).slice(2);this.form.patientId=null;this.form.settleId=this.meta.settlements[0]?.id||null;this.form.doctorId=null;await this.loadSlots();this.patients=await api.get('/patients',{params:{q:''}})},async submit(){if(!this.form.patientId||!this.form.doctorId||!this.form.settleId)return this.$message.warning('请选择患者、结算类别与出诊医生');try{await this.$confirm('确定挂号并记录已收取挂号费吗？','确认挂号',{type:'warning'})}catch{return}this.saving=true;try{await api.post('/registrations',this.form);this.$message.success('挂号成功');this.dialog=false;this.load()}catch(e){this.$message.error(e.message)}finally{this.saving=false}},async cancel(row){try{await this.$confirm(`确定退回 ${row.real_name} 的未看诊挂号及挂号费？`,'退号确认',{type:'warning'})}catch{return}try{await api.post(`/registrations/${row.id}/cancel`);this.$message.success('退号成功');this.load()}catch(e){this.$message.error(e.message)}}}}</script>
